#include <bits/stdc++.h>
using namespace std;

const int MAX = 511;
const int MOD = 998244353;
const int INV = 499122177;

inline int add(int a, int b) {
    int s = a + b;
    if (s >= MOD) s -= MOD;
    return s;
}

inline int mult(int a, int b) {
    return (int)((1LL * a * b) % MOD);
}

int dp[MAX + 1][MAX + 1];
int ndp[MAX + 1][MAX + 1];
int nums[MAX + 1];
int div2[MAX + 1];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    if (n == 1) {
        cout << 0 << '\n';
        return 0;
    }

    memset(dp, 0, sizeof(dp));
    dp[1][1] = 2;

    int lim = min(n, k);
    for (int pos = 0; pos < n; ++pos) {
        memset(ndp, 0, sizeof(ndp));
        for (int i = 1; i <= lim; ++i) {
            for (int j = 1; j <= lim; ++j) {
